def schema(g):
    url = f'https://nexalyplanner.com/guides/{g["slug"]}/'
    return ('{"@context":"https://schema.org","@type":"TechArticle","headline":"' + escape(g['h1'], quote=True) +
            '","description":"' + escape(g['description'], quote=True) + '","image":"https://nexalyplanner.com' + g['image'] +
            '","mainEntityOfPage":"' + url + '","author":{"@type":"Organization","name":"NexalyPlanner","url":"https://nexalyplanner.com/about/"},' +
            '"publisher":{"@type":"Organization","name":"NexalyPlanner","url":"https://nexalyplanner.com/"},"datePublished":"2026-09-16","dateModified":"2026-09-19","inLanguage":"en-US"}')

def head(g, collection=False):
    structured = ('{"@context":"https://schema.org","@type":"CollectionPage","name":"' + escape(g['h1'], quote=True) +
                  '","description":"' + escape(g['description'], quote=True) + '","url":"https://nexalyplanner.com/guides/"}') if collection else schema(g)
    return f'''<!doctype html><html lang="en-US"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="index,follow"><title>{escape(g['title'])}</title><meta name="description" content="{escape(g['description'], quote=True)}"><meta property="og:image" content="https://nexalyplanner.com{g['image']}"><meta property="og:image:alt" content="{escape(g['image_alt'], quote=True)}"><meta name="twitter:card" content="summary_large_image"><meta name="date" content="2026-09-16"><style>{STYLE}</style><link rel="stylesheet" href="/assets/css/style.css?v=2"><script type="application/ld+json">{structured}</script></head><body>'''

def guide_page(g):
    toc = ''.join(f'<li><a href="#step-{i}">{escape(title)}</a></li>' for i,(title,_) in enumerate(g['steps'],1))
    steps = ''.join(f'<section class="guide-step" id="step-{i}"><h3><span class="number">{i}</span>{escape(title)}</h3><p>{body}</p></section>' for i,(title,body) in enumerate(g['steps'],1))
    rows = ''.join(f'<tr><td>{escape(when)}</td><td>{escape(action)}</td></tr>' for when,action in g['routine_rows'])
    fixes = ''.join(f'<h3>{escape(title)}</h3><p>{escape(body)}</p>' for title,body in g['troubleshooting'])
    related = ''.join(f'<li><a href="{url}">{escape(label)}</a></li>' for label,url in g['related'])
    menus = ''
    example = ''
    limits = ''
    extra_toc = ''
    if g.get('menu_rows'):
        menu_rows = ''.join(f'<tr><td><strong>{escape(name)}</strong></td><td>{escape(purpose)}</td></tr>' for name,purpose in g['menu_rows'])
        menus = f'<h2 id="screens">Menu and screen map</h2><p>Use this map to understand where each record belongs before entering live data.</p><div class="guide-table"><table><thead><tr><th>Menu or screen</th><th>What it controls</th></tr></thead><tbody>{menu_rows}</tbody></table></div>'
        example_items = ''.join(f'<li>{escape(item)}</li>' for item in g['example_steps'])
        example = f'<h2 id="example">{escape(g["example_title"])}</h2><ol>{example_items}</ol><p>After the example, compare the dashboard and source records. If a total is unexpected, correct the original transaction rather than editing an unrelated summary.</p>'
        limit_items = ''.join(f'<li>{escape(item)}</li>' for item in g['limitations'])
        limits = f'<h2 id="limits">What the product does not do</h2><ul>{limit_items}</ul>'
        extra_toc = '<li><a href="#screens">Menus and screens</a></li><li><a href="#example">Worked example</a></li><li><a href="#limits">Limitations</a></li>'
    return head(g) + NAV + f'''<header class="guide-hero"><div class="kicker">NEXALY PRODUCT GUIDE</div><h1>{escape(g['h1'])}</h1><p>{escape(g['description'])}</p></header><main class="guide-main"><nav class="guide-crumbs" aria-label="Breadcrumb"><a href="/">Home</a> › <a href="/guides/">Product Guides</a> › {escape(g['product'])}</nav><div class="guide-layout"><article class="guide-article"><figure><img src="{g['image']}" width="1200" height="750" alt="{escape(g['image_alt'], quote=True)}" fetchpriority="high"><figcaption>Product interface shown for orientation. Labels may vary slightly by screen size.</figcaption></figure><p>{escape(g['intro'])}</p><div class="guide-quick"><strong>Quick start:</strong> {escape(g['quick'])}</div>{menus}<h2>Set up and use the planner</h2>{steps}{example}<h2>A simple routine to maintain your records</h2><div class="guide-table"><table><thead><tr><th>When</th><th>What to do</th></tr></thead><tbody>{rows}</tbody></table></div><h2 id="data">Protect your offline data</h2><p>Your planner records are stored locally in the browser on the device you use. They do not automatically sync to another browser or device. Create a supported backup regularly, especially before clearing browser data, moving the HTML file, changing devices or reinstalling a browser. Keep dated backup copies in a location you control and test that you can locate them.</p>{limits}<h2>Troubleshooting</h2>{fixes}<div class="guide-cta"><h2>View the {escape(g['product'])}</h2><p>See the full feature list, screenshots, download contents and current purchase terms on the product page.</p><a href="{g['product_url']}">View product details</a></div><div class="guide-related"><h2>Related planning articles</h2><ul>{related}</ul></div></article><aside class="guide-aside"><h2>In this guide</h2><ol>{extra_toc}{toc}<li><a href="#data">Data and backups</a></li></ol><hr><p><strong>Updated:</strong><br>September 19, 2026</p><p><a href="/guides/">All product guides</a></p></aside></div></main>''' + SHELL

def index_page():
    cards = ''.join(f'''<a class="guide-card" href="/guides/{g['slug']}/"><img src="{g['image']}" alt="{escape(g['image_alt'], quote=True)}" loading="lazy"><div><h2>{escape(g['h1'])}</h2><p>{escape(g['description'])}</p></div></a>''' for g in GUIDES)
    meta = {'title':'NexalyPlanner Product Guides & User Manuals','description':'Open 15 step-by-step NexalyPlanner user guides for product setup, menus, workflows, worked examples, offline data, backups and troubleshooting.','image':'/images/og-default.jpg'}
    return head(meta | {'slug':'','h1':meta['title'],'image_alt':'NexalyPlanner product guides and user manuals'}, collection=True) + NAV + f'''<header class="guide-hero"><div class="kicker">NEXALY HELP CENTER</div><h1>Product Guides &amp; User Manuals</h1><p>Step-by-step setup, daily workflows, offline data guidance and troubleshooting for NexalyPlanner products.</p></header><main class="guide-main"><nav class="guide-crumbs" aria-label="Breadcrumb"><a href="/">Home</a> › Product Guides</nav><section class="guides-grid">{cards}</section></main>''' + SHELL

for guide in GUIDES:
    target = ROOT / 'guides' / guide['slug'] / 'index.html'
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(guide_page(guide))

index = ROOT / 'guides/index.html'
index.parent.mkdir(parents=True, exist_ok=True)
index.write_text(index_page())

# Give every new manual a contextual, crawlable inbound link from its product.
for guide in GUIDES[5:]:
    product_path = ROOT / guide['product_url'].strip('/') / 'index.html'
    product_html = product_path.read_text()
    href = f'/guides/{guide["slug"]}/'
    if href not in product_html:
        anchor = f'<a href="{href}">Read the complete {escape(guide["product"])} user guide</a>'
        pattern = r'(<(?P<tag>ul|p) class="pd-guides">)'
        def add_product_guide(match):
            return match.group(1) + (f'<li>{anchor}</li>' if match.group('tag') == 'ul' else anchor + '. ')
        product_html, count = re.subn(pattern, add_product_guide, product_html, count=1)
        if count != 1:
            raise RuntimeError(f'Could not find related-guide block in {product_path}')
        product_path.write_text(product_html)
print(f'Built {len(GUIDES)} guides and the guides index')
